<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigAllowRecoverPassAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigAllowRecoverPassAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowRecoverPass,
 * getAllowRecoverPass/allowRecoverPass accessors, and isAllowRecoverPassChanged with/without original.
 */
class TenantConfigAllowRecoverPassAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowRecoverPass creates a new instance with the AllowRecoverPass set
     * from a string value, and getAllowRecoverPass returns the primitive string.
     */
    public function testWithAllowRecoverPassFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRecoverPassAccessorUnitTest();

        // Act
        $result = $holder->withAllowRecoverPass(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isAllowRecoverPass());
    }
    /**
     * Asserts that withallowRecoverPass has access to the value object
     * from a string value, and getAllowRecoverPass returns the primitive string.
     */
    public function testWithAllowRecoverPassFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRecoverPassAccessorUnitTest();

        // Act
        $result = $holder->withAllowRecoverPass(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->allowRecoverPass()->value());
    }
    public function testChangedAllowRecoverPass(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRecoverPassAccessorUnitTest();
        $original = $holder->withAllowRecoverPass(true);
        $same = $holder->withAllowRecoverPass(true);
        $modified = $holder->withAllowRecoverPass(false);

        // Act
        $unchanged = $holder->isAllowRecoverPassChanged();
        $withSame = $original->isAllowRecoverPassChanged($same);
        $withDiferent = $original->isAllowRecoverPassChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigAllowRecoverPassAccessorUnitTest
{
    use TenantConfigAllowRecoverPassAccessor;
}
